<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
type Template = { id: number; name: string; typeId: number; typeName: string; status: string; versionNo: number; updatedAt: string }
type Detail = Template & { content: string; variables: string[] }
type Type = { id: number; name: string; subtype: string; category: string }
const props = defineProps<{ api: string; role: string; types: Type[] }>()
const templates = ref<Template[]>([]); const selected = ref<Detail | null>(null); const versions = ref<Detail[]>([]); const loading = ref(false); const error = ref(''); const keyword = ref(''); const status = ref('全部状态'); const selectedType = ref('全部类型'); const showCreate = ref(false)
const form = ref({ name: '', typeId: 1, content: '合同名称：{{contract.name}}\n合同编号：{{contract.no}}\n交易对方：{{party.name}}\n\n一、双方权利义务\n' })
const filtered = computed(() => templates.value.filter(item => (!keyword.value || [item.name, item.typeName].some(v => v.toLowerCase().includes(keyword.value.toLowerCase()))) && (status.value === '全部状态' || item.status === status.value) && (selectedType.value === '全部类型' || item.typeName === selectedType.value)))
const headers = () => ({ 'Content-Type': 'application/json', 'X-Role': props.role })
async function request<T>(path: string, options: RequestInit = {}) { const response = await fetch(`${props.api}${path}`, { ...options, headers: { ...headers(), ...(options.headers || {}) } }); if (!response.ok) throw new Error((await response.text()) || '请求失败'); return response.json() as Promise<T> }
async function load() { loading.value = true; try { templates.value = await request<Template[]>('/api/templates') } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
async function open(item: Template) { try { selected.value = await request<Detail>(`/api/templates/${item.id}`); versions.value = await request<Detail[]>(`/api/templates/${item.id}/versions`) } catch (e) { error.value = (e as Error).message } }
async function create() { if (!form.value.name || !form.value.content) { error.value = '请填写模板名称和正文'; return }; try { const item = await request<Detail>('/api/templates', { method: 'POST', body: JSON.stringify(form.value) }); showCreate.value = false; await load(); await open(item) } catch (e) { error.value = (e as Error).message } }
async function addVersion() { if (!selected.value?.content.trim()) return; try { selected.value = await request<Detail>(`/api/templates/${selected.value.id}/versions`, { method: 'POST', body: JSON.stringify({ content: selected.value.content }) }); await open(selected.value) } catch (e) { error.value = (e as Error).message } }
async function action(name: string) { if (!selected.value) return; try { selected.value = await request<Detail>(`/api/templates/${selected.value.id}/${name}`, { method: 'POST' }); await load(); await open(selected.value) } catch (e) { error.value = (e as Error).message } }
function typeName(id: number) { return props.types.find(item => item.id === id)?.name || '未配置类型' }
onMounted(load)
</script>
<template>
  <section class="template-workspace page-section"><div class="page-header"><div><p class="eyebrow">系统管理 / 合同模板配置</p><h1>合同模板配置</h1><p class="page-desc">统一维护模板版本、变量来源和适用合同类型。新版本只影响新建合同。</p></div><button class="primary-action" @click="showCreate=true">＋ 新建模板</button></div><div v-if="error" class="fulfillment-error">{{ error }}<button @click="error=''">关闭</button></div><section class="panel template-filter"><label class="search-box">⌕<input v-model="keyword" placeholder="搜索模板名称或合同类型" /></label><label class="filter-field"><span>适用类型</span><select v-model="selectedType"><option>全部类型</option><option v-for="item in props.types" :key="item.id">{{ item.name }}</option></select></label><label class="filter-field"><span>模板状态</span><select v-model="status"><option>全部状态</option><option>DRAFT</option><option>PUBLISHED</option><option>DISABLED</option></select></label><span class="result-count">{{ filtered.length }} 个模板</span></section><div class="template-layout"><section class="panel template-list"><div class="section-heading"><div><h2>模板库</h2><p class="section-caption">按类型和版本管理可用模板</p></div></div><div v-if="loading" class="inline-empty">正在加载...</div><div v-else-if="!filtered.length" class="empty-state"><strong>暂无匹配模板</strong><span>调整筛选条件或新建模板。</span></div><button v-for="item in filtered" :key="item.id" class="template-row" :class="{ active: selected?.id === item.id }" @click="open(item)"><span><b>{{ item.name }}</b><small>{{ item.typeName }} · v{{ item.versionNo }}</small></span><span><i class="status-tag">{{ item.status === 'PUBLISHED' ? '已发布' : item.status === 'DISABLED' ? '已停用' : '草稿' }}</i><small>{{ new Date(item.updatedAt).toLocaleDateString('zh-CN') }}</small></span></button></section><section v-if="selected" class="panel template-detail"><div class="template-detail-head"><div><p class="eyebrow">模板详情</p><h2>{{ selected.name }}</h2><span>{{ selected.typeName }} · 当前版本 v{{ selected.versionNo }}</span></div><div class="template-actions"><button v-if="selected.status !== 'PUBLISHED'" class="secondary-action" @click="action('publish')">发布版本</button><button v-if="selected.status !== 'PUBLISHED'" class="secondary-action" @click="action('toggle')">{{ selected.status === 'DISABLED' ? '启用模板' : '停用模板' }}</button></div></div><div class="template-meta"><div><span>适用合同类型</span><b>{{ selected.typeName }}</b></div><div><span>当前状态</span><b>{{ selected.status }}</b></div><div><span>变量数量</span><b>{{ selected.variables.length }}</b></div></div><div class="template-editor"><div class="section-heading"><div><h3>模板正文</h3><p class="section-caption">变量必须来自字段字典，当前识别到的变量不可随意扩展。</p></div><button class="secondary-action" @click="addVersion">保存新版本</button></div><textarea v-model="selected.content" rows="14" /></div><div class="variable-box"><h3>已识别变量</h3><span v-for="item in selected.variables" :key="item" class="variable-tag">{{ item }}</span><span v-if="!selected.variables.length" class="muted">暂无变量</span></div><div class="version-history"><h3>版本历史</h3><div v-for="item in versions" :key="item.versionNo"><span><b>v{{ item.versionNo }}</b><small>{{ item.variables.length }} 个变量</small></span><i class="status-tag">{{ item.versionNo === selected.versionNo ? '当前版本' : '历史版本' }}</i></div></div></section><section v-else class="panel template-detail template-detail-empty"><strong>选择一个模板查看详情</strong><span>可在此维护正文、变量、版本和发布状态。</span></section></div><section v-if="showCreate" class="panel template-create"><div class="section-heading"><div><h2>新建模板</h2><p class="section-caption">模板发布前请确认适用类型和变量来源。</p></div><button class="ghost-button" @click="showCreate=false">取消</button></div><div class="form-grid"><label>模板名称<input v-model="form.name" placeholder="例如：通用服务合同" /></label><label>适用合同类型<select v-model.number="form.typeId"><option v-for="item in props.types" :key="item.id" :value="item.id">{{ item.name }} · {{ item.subtype }}</option></select></label><label class="full-width">模板正文<textarea v-model="form.content" rows="10" /></label></div><div class="form-footer"><span class="muted">模板生成合同后，已生成正文不会随模板变化</span><button class="primary-action" @click="create">保存模板</button></div></section></section>
</template>
